package io.github.miklires.mevents.command;
import io.github.miklires.mevents.event.*;import org.bukkit.command.*;import org.bukkit.entity.Player;import java.util.*;
public final class EventCommand implements CommandExecutor,TabCompleter{private final EventService service;private final Runnable reload;public EventCommand(EventService service,Runnable reload){this.service=service;this.reload=reload;}public boolean onCommand(CommandSender sender,Command command,String label,String[] args){if(args.length==0||args[0].equalsIgnoreCase("list")){sender.sendMessage("§6Шаблоны: §f"+String.join(", ",service.templateIds()));sender.sendMessage("§6Активные: §f"+service.runtimeViews().stream().map(v->v.template()+" ("+v.id()+")").toList());return true;}if(args[0].equalsIgnoreCase("status")||args[0].equalsIgnoreCase("time")){var active=service.runtimeViews();sender.sendMessage(active.isEmpty()?"§7Активных событий нет.":"§6Активные события: §f"+active);return true;}if(!sender.hasPermission("mevents.admin")){sender.sendMessage("§cНедостаточно прав.");return true;}try{switch(args[0].toLowerCase(Locale.ROOT)){case "start"->{if(args.length<2)throw new IllegalArgumentException("/event start <template>");service.start(args[1]).whenComplete((run,error)->{if(error!=null)sender.sendMessage("§c"+root(error).getMessage());else sender.sendMessage("§aСобытие запланировано: "+run.runId());});}case "stop"->{if(args.length<2)throw new IllegalArgumentException("/event stop <run-id>");service.cancel(UUID.fromString(args[1]),"stopped by "+sender.getName()).thenAccept(ok->sender.sendMessage(ok?"§aСобытие остановлено.":"§cСобытие не найдено."));}case "reload"->{if(!sender.hasPermission("mevents.reload"))throw new IllegalArgumentException("Недостаточно прав");reload.run();sender.sendMessage("§aКонфигурация перезагружена.");}default->throw new IllegalArgumentException("/event <list|status|start|stop|reload>");}}catch(Exception e){sender.sendMessage("§c"+e.getMessage());}return true;}private static Throwable root(Throwable e){while(e.getCause()!=null)e=e.getCause();return e;}public List<String> onTabComplete(CommandSender sender,Command command,String alias,String[] args){if(args.length==1)return List.of("list","status","time","start","stop","reload").stream().filter(v->v.startsWith(args[0].toLowerCase())).toList();if(args.length==2&&args[0].equalsIgnoreCase("start"))return service.templateIds().stream().filter(v->v.startsWith(args[1])).toList();if(args.length==2&&args[0].equalsIgnoreCase("stop"))return service.runtimeViews().stream().map(v->v.id().toString()).filter(v->v.startsWith(args[1])).toList();return List.of();}}
